import{_ as t,o as a,c as o,ae as r}from"./chunks/framework.Dh1jimFm.js";const u=JSON.parse('{"title":"Image Extractor (Superimage)","description":"","frontmatter":{},"headers":[],"relativePath":"tools/image-extractor.md","filePath":"tools/image-extractor.md"}'),i={name:"tools/image-extractor.md"};function s(l,e,n,c,g,d){return a(),o("div",null,e[0]||(e[0]=[r('<h1 id="image-extractor-superimage" tabindex="-1">Image Extractor (Superimage) <a class="header-anchor" href="#image-extractor-superimage" aria-label="Permalink to &quot;Image Extractor (Superimage)&quot;">​</a></h1><p>The Image Extractor pulls embedded images out of DOCX files and saves them as numbered PNG files. It also includes a built-in preview so you can quickly review what was extracted.</p><h2 id="where-to-find-it" tabindex="-1">Where to find it <a class="header-anchor" href="#where-to-find-it" aria-label="Permalink to &quot;Where to find it&quot;">​</a></h2><ul><li><strong>Tools → Image Extractor (Superimage)...</strong></li><li>Or: <strong>Project resources</strong> → <strong>🎯 Image Context</strong> (the Image Extractor lives in the bottom section of that tab)</li></ul><h2 id="extract-images-from-a-docx" tabindex="-1">Extract images from a DOCX <a class="header-anchor" href="#extract-images-from-a-docx" aria-label="Permalink to &quot;Extract images from a DOCX&quot;">​</a></h2><ol><li>Add input files: <ul><li><strong>📄 Add File</strong> to pick DOCX files</li><li><strong>📁 Folder</strong> to add all DOCX files from a folder</li></ul></li><li>Choose an output strategy: <ul><li>Enable <strong>📁 Auto-folder</strong> to create an <code>Images</code> folder next to each DOCX</li><li>Or set a single output directory in the <strong>Output directory</strong> field</li></ul></li><li>Set <strong>Prefix</strong> (default <code>Fig.</code>).</li><li>Click <strong>🖼️ Extract Images</strong>.</li><li>Use <strong>📂 Extracted Files (click to preview)</strong> to preview images.</li></ol><h2 id="using-extracted-images-as-ai-context" tabindex="-1">Using extracted images as AI context <a class="header-anchor" href="#using-extracted-images-as-ai-context" aria-label="Permalink to &quot;Using extracted images as AI context&quot;">​</a></h2><p>If you also use <strong>Image Context</strong>, you can load a folder of figures so Supervertaler can attach relevant images automatically during AI translation (for example when the text references “Figure 2A”).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Image Extractor is about getting the images out of DOCX. Image Context is about feeding those images into AI translation when needed.</p></div>',9)]))}const x=t(i,[["render",s]]);export{u as __pageData,x as default};
